import Foundation

enum OfficeTemplateData {
    static func data(for fileExtension: String) -> Data? {
        switch FileTemplate.normalizedExtension(fileExtension) {
        case "docx":
            return Data(base64Encoded: docxBase64)
        case "xlsx":
            return Data(base64Encoded: xlsxBase64)
        case "pptx":
            return Data(base64Encoded: pptxBase64V2)
        default:
            return nil
        }
    }

    private static let docxBase64 = """
    
    """

    private static let xlsxBase64 = """
    
    """

    private static let pptxBase64V2 = """
    
    """

    private static let pptxBase64 = """
    
    """
}
